import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Calendar, Clock, Send, Trash2, Key, Plus, Check, X } from 'lucide-react';
import './App.css';

function App() {
  // Animation variants
  const fadeIn = {
    initial: { opacity: 0, y: 20 },
    animate: { opacity: 1, y: 0 },
    exit: { opacity: 0, y: -20 }
  };
  const [apiKey, setApiKey] = useState('');
  const [savedKey, setSavedKey] = useState('');
  const [posts, setPosts] = useState([]);
  const [newPost, setNewPost] = useState({ content: '', platform: 'twitter', scheduledDate: '' });
  const [templates, setTemplates] = useState([
    { id: 1, name: 'Product Launch', content: 'Exciting news! 🎉 We\'re launching [Product Name]! Stay tuned for more details. #NewLaunch #Business' },
    { id: 2, name: 'Special Offer', content: '🔥 Special offer alert! Get [X]% off on all our products today only! Use code: [CODE] #SpecialOffer #Deal' },
    { id: 3, name: 'Business Update', content: 'We\'re excited to announce that we\'re now [Update]! Thank you for being part of our journey! #BusinessGrowth' }
  ]);

  useEffect(() => {
    const savedApiKey = localStorage.getItem('openai_api_key');
    if (savedApiKey) {
      setSavedKey(savedApiKey);
    }
    const savedPosts = localStorage.getItem('scheduled_posts');
    if (savedPosts) {
      setPosts(JSON.parse(savedPosts));
    }
  }, []);

  const handleSaveApiKey = () => {
    localStorage.setItem('openai_api_key', apiKey);
    setSavedKey(apiKey);
    setApiKey('');
  };

  const handleSchedulePost = () => {
    const post = {
      id: Date.now(),
      ...newPost,
      status: 'scheduled'
    };
    const updatedPosts = [...posts, post];
    setPosts(updatedPosts);
    localStorage.setItem('scheduled_posts', JSON.stringify(updatedPosts));
    setNewPost({ content: '', platform: 'twitter', scheduledDate: '' });
  };

  const handleUseTemplate = (template) => {
    setNewPost({
      ...newPost,
      content: template.content
    });
  };

  const handleDeletePost = (postId) => {
    const updatedPosts = posts.filter(post => post.id !== postId);
    setPosts(updatedPosts);
    localStorage.setItem('scheduled_posts', JSON.stringify(updatedPosts));
  };

  return (
    <div className="min-h-screen bg-gray-100">
      <nav className="bg-white shadow-lg">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <h1 className="text-2xl font-bold text-gray-800">Local Business Marketing Assistant</h1>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 py-8">
        {/* API Key Section */}
        <section className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 className="text-xl font-semibold mb-4">OpenAI API Configuration</h2>
          {!savedKey ? (
            <div className="flex gap-4">
              <input
                type="password"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                placeholder="Enter your OpenAI API key"
                className="flex-1 p-2 border rounded"
              />
              <button
                onClick={handleSaveApiKey}
                className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
              >
                Save API Key
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-4">
              <span className="text-green-600">✓ API Key configured</span>
              <button
                onClick={() => {
                  localStorage.removeItem('openai_api_key');
                  setSavedKey('');
                }}
                className="text-red-600 hover:text-red-700"
              >
                Remove Key
              </button>
            </div>
          )}
        </section>

        {/* Post Scheduler Section */}
        <section className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 className="text-xl font-semibold mb-4">Post Scheduler</h2>
          <div className="space-y-4">
            <textarea
              value={newPost.content}
              onChange={(e) => setNewPost({ ...newPost, content: e.target.value })}
              placeholder="Write your post content..."
              className="w-full p-2 border rounded h-32"
            />
            <div className="flex gap-4">
              <select
                value={newPost.platform}
                onChange={(e) => setNewPost({ ...newPost, platform: e.target.value })}
                className="p-2 border rounded"
              >
                <option value="twitter">Twitter</option>
                <option value="facebook">Facebook</option>
                <option value="linkedin">LinkedIn</option>
              </select>
              <input
                type="datetime-local"
                value={newPost.scheduledDate}
                onChange={(e) => setNewPost({ ...newPost, scheduledDate: e.target.value })}
                className="p-2 border rounded"
              />
              <button
                onClick={handleSchedulePost}
                disabled={!newPost.content || !newPost.scheduledDate}
                className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 disabled:bg-gray-400"
              >
                Schedule Post
              </button>
            </div>
          </div>
        </section>

        {/* Templates Section */}
        <section className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 className="text-xl font-semibold mb-4">Marketing Templates</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {templates.map((template) => (
              <div key={template.id} className="border rounded p-4">
                <h3 className="font-semibold mb-2">{template.name}</h3>
                <p className="text-gray-600 mb-4">{template.content}</p>
                <button
                  onClick={() => handleUseTemplate(template)}
                  className="text-blue-600 hover:text-blue-700"
                >
                  Use Template
                </button>
              </div>
            ))}
          </div>
        </section>

        {/* Scheduled Posts Section */}
        <section className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4">Scheduled Posts</h2>
          <div className="space-y-4">
            {posts.map((post) => (
              <div key={post.id} className="border rounded p-4">
                <div className="flex justify-between items-start mb-2">
                  <span className="capitalize font-semibold">{post.platform}</span>
                  <button
                    onClick={() => handleDeletePost(post.id)}
                    className="text-red-600 hover:text-red-700"
                  >
                    Delete
                  </button>
                </div>
                <p className="text-gray-600 mb-2">{post.content}</p>
                <p className="text-sm text-gray-500">
                  Scheduled for: {new Date(post.scheduledDate).toLocaleString()}
                </p>
              </div>
            ))}
          </div>
        </section>
      </main>
    </div>
  );
}

export default App;
